package net.civeira.phylax.feature.access.oauthclient.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class DefaultMaxAgeVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property default max age of oauth client ")
  void test_default_max_age_v_o_builder() {
    Assertions.assertFalse(DefaultMaxAgeVO.nullValue().getDefaultMaxAge().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(DefaultMaxAgeVO.tryFrom(null).getDefaultMaxAge().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals(1, DefaultMaxAgeVO.from(1).getDefaultMaxAge().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> DefaultMaxAgeVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + 1 + "]", DefaultMaxAgeVO.from(1).toString());
  }
}
